def summarize(rows):
    """Take a list of dicts with 'region' and 'revenue' keys and return
    a dict mapping each region to the total revenue as a float.
    Rows with missing or unparseable revenue are ignored."""
    totals = {}
    for row in rows:
        region = row.get('region')
        raw = row.get('revenue')
        if region is None or raw is None:
            continue
        try:
            revenue = float(raw)
        except (TypeError, ValueError):
            continue
        totals[region] = totals.get(region, 0.0) + revenue
    return totals

