from summarize import summarize


def test_basic():
    rows = [
        {'region': 'NA', 'revenue': 100},
        {'region': 'EU', 'revenue': 200},
        {'region': 'NA', 'revenue': 50},
    ]
    assert summarize(rows) == {'NA': 150.0, 'EU': 200.0}


def test_numeric_strings():
    rows = [
        {'region': 'APAC', 'revenue': '300'},
        {'region': 'APAC', 'revenue': '150.5'},
    ]
    assert summarize(rows) == {'APAC': 450.5}


def test_missing_revenue_ignored():
    rows = [
        {'region': 'NA', 'revenue': None},
        {'region': 'EU', 'revenue': 100},
    ]
    assert summarize(rows) == {'EU': 100.0}


def test_unparseable_revenue_ignored():
    rows = [
        {'region': 'NA', 'revenue': 'abc'},
        {'region': 'EU', 'revenue': 50},
    ]
    assert summarize(rows) == {'EU': 50.0}


def test_empty_input():
    assert summarize([]) == {}


def test_all_invalid():
    rows = [
        {'region': 'NA', 'revenue': 'bad'},
        {'region': None, 'revenue': 10},
        {'region': 'EU', 'revenue': None},
    ]
    assert summarize(rows) == {}


def test_returns_floats():
    rows = [{'region': 'X', 'revenue': 10}]
    result = summarize(rows)
    assert isinstance(result['X'], float)

